func verifyIndex(dbPath string) (count int, maxTS time.Time, err error) {
	idx, err := index.NewIndex(dbPath)
	if err != nil {
		return
	}
	defer idx.Close()

	entries, err := idx.AllEntries(context.Background())
	if err != nil {
		// Fall back to counting via raw query if AllEntries doesn't exist
		return countEntriesRaw(dbPath)
	}

	count = len(entries)
	for _, e := range entries {
		if e.CreatedAt.After(maxTS) {
			maxTS = e.CreatedAt
		}
	}
	return
}

func countEntriesRaw(dbPath string) (count int, maxTS time.Time, err error) {
	// Direct SQL fallback
	db, err2 := index.NewIndex(dbPath)
	if err2 != nil {
		err = err2
		return
	}
	defer db.Close()

	// Use the index's DB directly — we'll count via the public API
	// For now, just return what we can
	return 0, time.Time{}, fmt.Errorf("AllEntries not available, needs implementation")
